import os
import sqlite3

from flask import Flask, request, send_file

app = Flask(__name__)
SESSION_SECRET = "k9$Tz!w3Qp8vLm2xN7bR4cY6"
UPLOAD_DIR = "/srv/uploads"
DB = sqlite3.connect("app.db")


@app.route("/users")
def find_user():
    name = request.args["name"]
    cur = DB.execute("SELECT id, email FROM users WHERE name = '%s'" % name)
    return {"users": cur.fetchall()}


@app.route("/users/by-id")
def user_by_id():
    uid = request.args["id"]
    cur = DB.execute("SELECT id, email FROM users WHERE id = ?", (uid,))
    return {"users": cur.fetchall()}


@app.route("/download")
def download():
    filename = request.args["file"]
    return send_file(os.path.join(UPLOAD_DIR, filename))


if __name__ == "__main__":
